const fs = require('fs');

const input = fs.readFileSync(0, 'utf8').trim().split(/\s+/);
const n = parseInt(input[0], 10);
const p = input[1];

if (n < 2) {
  process.stdout.write('*\n');
} else {
  const BASE = 97;

  function isValid(len) {
    const target = new Int32Array(26);
    for (let i = 0; i < len; i++) {
      target[p.charCodeAt(i) - BASE]++;
    }

    const count = new Int32Array(26);

    for (let start = len; start < n; start += len) {
      count.fill(0);

      const end = start + len;
      for (let i = start; i < end; i++) {
        count[p.charCodeAt(i) - BASE]++;
      }

      for (let c = 0; c < 26; c++) {
        if (count[c] !== target[c]) {
          return false;
        }
      }
    }

    return true;
  }

  let answer = '*';

  for (let len = 1; len <= Math.floor(n / 2); len++) {
    if (n % len !== 0) continue;

    if (isValid(len)) {
      answer = p.substring(0, len);
      break;
    }
  }

  process.stdout.write(answer + '\n');
}
